"""Observability for one triggered silence timeout."""

from __future__ import annotations

from contextlib import contextmanager
from typing import Iterator, Optional

from opentelemetry.trace import Span

from rasa.tracing.voice.metrics import (
    InteractionOutcome,
    record_silence_timeout_metric,
)
from rasa.tracing.voice.shared import semconv
from rasa.tracing.voice.spans import voice_stage_span


class SilenceDecisionRecorder:
    """Record one triggered timeout as span events and a timeout metric.

    Records detection when the span opens and acceptance after the timeout
    event is enqueued. Span writes are skipped when the wrapped span is
    non-recording (tracing disabled).
    """

    def __init__(self, span: Span) -> None:
        self.span = span

    def record_accepted(self, *, timeout_s: Optional[float] = None) -> None:
        """Record that the silence timeout was published as a turn event.

        Args:
            timeout_s: Configured silence timeout in seconds. This is
                configuration metadata, not a measured duration.
        """
        record_silence_timeout_metric(
            outcome=InteractionOutcome.ACCEPTED, timeout_s=timeout_s
        )
        if self.span.is_recording():
            self.span.add_event(semconv.EVENT_SILENCE_ACCEPTED)


@contextmanager
def handle_silence_span() -> Iterator[SilenceDecisionRecorder]:
    """Open a `handle silence` span around one elapsed silence timeout.

    The span covers decision processing after the timer fires.

    Yields:
        The decision recorder. Span writes are no-ops without tracing; metrics
        remain active when configured.
    """
    with voice_stage_span(semconv.SPAN_NAME_HANDLE_SILENCE) as span:
        if span.is_recording():
            span.add_event(semconv.EVENT_SILENCE_DETECTED)
        yield SilenceDecisionRecorder(span)
